import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** A sheet's claim templates. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/claim-templates")
public class ClaimTemplateController {

    public record ClaimTemplateView(long id, String name, String amount, String note) {

        static ClaimTemplateView of(ClaimTemplate t) {
            return new ClaimTemplateView(t.getId(), t.getName(), t.getAmount().setScale(2).toPlainString(),
                    t.getNote());
        }
    }

    public record ClaimTemplateRequest(
            @Size(max = 200) String name,
            @NotNull @Digits(integer = 13, fraction = 2) BigDecimal amount,
            @Size(max = 1000) String note) {
    }

    private final ClaimTemplateService service;

    public ClaimTemplateController(ClaimTemplateService service) {
        this.service = service;
    }

    /** The sheet's claim templates, by name. */
    @GetMapping
    public List<ClaimTemplateView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return service.list(sheetId.trim()).stream().map(ClaimTemplateView::of).toList();
    }

    /** Save a template, replacing the one by its name. */
    @PostMapping
    public ClaimTemplateView save(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ClaimTemplateRequest request) {
        return ClaimTemplateView.of(
                service.save(sheetId.trim(), user.trim(), request.name(), request.amount(), request.note()));
    }

    /** A template that cannot be saved is refused with the reason, for the screen to show. */
    @ExceptionHandler(TemplateRefusedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> refused(TemplateRefusedException e) {
        return Map.of("message", e.getMessage());
    }
}
package net.officefloor.hq.app.template;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;

/** A sheet's claim template: a name, and the amount and note a claim made from it takes at that moment. */
@Entity
@Table(name = "claim_template")
public class ClaimTemplate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "amount", nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(name = "note", nullable = false)
    private String note;

    protected ClaimTemplate() {
    }

    public ClaimTemplate(String sheetId, String name, BigDecimal amount, String note) {
        this.sheetId = sheetId;
        this.name = name;
        this.amount = amount;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public String getNote() {
        return note;
    }

    /** Replace the template's amount and note: claims already made from it keep theirs. */
    public void replace(BigDecimal amount, String note) {
        this.amount = amount;
        this.note = note;
    }
}
package net.officefloor.hq.app.template;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ClaimTemplateRepository extends JpaRepository<ClaimTemplate, Long> {

    /** The sheet's claim templates, by name. */
    List<ClaimTemplate> findBySheetIdOrderByNameAsc(String sheetId);

    Optional<ClaimTemplate> findBySheetIdAndName(String sheetId, String name);
}
package net.officefloor.hq.app.template;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps each sheet's claim templates. */
@Service
public class ClaimTemplateService {

    private final ClaimTemplateRepository templates;
    private final SheetService sheets;
    private final Audit audit;

    public ClaimTemplateService(ClaimTemplateRepository templates, SheetService sheets, Audit audit) {
        this.templates = templates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's claim templates, by name. */
    @Transactional(readOnly = true)
    public List<ClaimTemplate> list(String sheetId) {
        return templates.findBySheetIdOrderByNameAsc(sheetId);
    }

    /** The sheet's template by the name; none by it is refused. */
    @Transactional(readOnly = true)
    public ClaimTemplate find(String sheetId, String name) {
        String n = name == null ? "" : name.trim();
        return templates.findBySheetIdAndName(sheetId, n)
                .orElseThrow(() -> new TemplateRefusedException("Choose a claim template."));
    }

    /** Save a template (name and note trimmed), replacing the one by the name; a blank name, or an amount a
     *  claim would refuse (a negative amount names no claim it corrects), is refused. */
    @Transactional
    public ClaimTemplate save(String sheetId, String user, String name, BigDecimal amount, String note) {
        sheets.today(sheetId);
        String n = name == null ? "" : name.trim();
        String t = note == null ? "" : note.trim();
        if (n.isEmpty()) {
            throw new TemplateRefusedException("Enter a template name.");
        }
        if (amount.signum() < 0) {
            throw new TemplateRefusedException("Enter an amount of 0.00 or more.");
        }
        BigDecimal a = amount.setScale(2);
        ClaimTemplate template = templates.findBySheetIdAndName(sheetId, n).orElse(null);
        if (template == null) {
            template = new ClaimTemplate(sheetId, n, a, t);
        } else {
            template.replace(a, t);
        }
        ClaimTemplate saved = templates.saveAndFlush(template);
        audit.recordOnCommit("TEMPLATE_SAVED sheet=" + sheetId + " by=" + user + " name=" + n + " amount="
                + a.toPlainString() + " note=" + t);
        return saved;
    }
}
package net.officefloor.hq.app.template;

/** A claim template that cannot be saved (a blank name, or an amount a claim would refuse), or used (none by
 *  the name). */
public class TemplateRefusedException extends RuntimeException {

    public TemplateRefusedException(String message) {
        super(message);
    }
}

